"""ABI 类型字符串的递归下降解析器。

语法（空白规则见下）::

    type       := elementary | tuple ，后接零个或多个数组后缀
    elementary := uintM | intM | address | bool | string | bytes | bytesM
    tuple      := '(' [type (',' type)*] ')'
    suffix     := '[]' | '[' [1-9][0-9]* ']'

空白（仅 ASCII 空白）只允许出现在：
1. 整个类型字符串的两端；
2. 元组中逗号的两侧。
其余位置的空白（类型词内部、括号内侧、数组语法内部等）一律报错。
输入必须完整解析，尾随任何非空白字符均报错。
"""

from __future__ import annotations

from ._exceptions import ABITypeError
from ._types import ABIType, ArrayType, ElementaryType, TupleType

_WHITESPACE = " \t\n\r\f\v"

#: 解析器括号递归的安全上限：语义嵌套上限（128 层）由类型对象构造时
#: 检查；此阈值仅用于在触及 Python 递归限制（实测约 500 层括号）前抛出
#: ABITypeError，远低于递归上限且高于任何合法输入。
_RECURSION_SAFETY_LIMIT = 200


class _Parser:
    def __init__(self, text: str) -> None:
        self._text = text
        self._pos = 0
        self._len = len(text)
        self._tuple_depth = 0

    def parse(self) -> ABIType:
        self._skip_whitespace()
        result = self._parse_type()
        self._skip_whitespace()
        if self._pos != self._len:
            raise self._error("存在无法解析的尾随内容")
        return result

    # ---- 通用构件 -------------------------------------------------------

    def _error(self, message: str) -> ABITypeError:
        return ABITypeError(f"无效的 ABI 类型 {self._text!r}（位置 {self._pos}）：{message}")

    def _skip_whitespace(self) -> None:
        text = self._text
        while self._pos < self._len and text[self._pos] in _WHITESPACE:
            self._pos += 1

    def _peek(self) -> str | None:
        if self._pos >= self._len:
            return None
        return self._text[self._pos]

    # ---- 类型 -----------------------------------------------------------

    def _parse_type(self) -> ABIType:
        ch = self._peek()
        if ch is None:
            raise self._error("类型不完整")
        if ch == "(":
            head: ABIType = self._parse_tuple()
        elif ch.isascii() and ch.isalpha():
            head = self._parse_elementary()
        else:
            raise self._error("此处应为基础类型或元组")
        return self._parse_suffixes(head)

    def _parse_elementary(self) -> ElementaryType:
        text = self._text
        start = self._pos
        while self._pos < self._len:
            ch = text[self._pos]
            if ch.isascii() and ch.isalnum():
                self._pos += 1
            else:
                break
        word = text[start:self._pos]
        return self._classify(word)

    def _classify(self, word: str) -> ElementaryType:
        if word in ("address", "bool", "string"):
            return ElementaryType(word)
        if word == "bytes":
            return ElementaryType("bytes")
        if word.startswith("bytes") and len(word) > len("bytes"):
            return self._sized_bytes(word)
        if word.startswith("uint") or word.startswith("int"):
            return self._sized_integer(word)
        raise self._error(f"不是合法的基础类型：{word!r}")

    def _digits_suffix(self, word: str, prefix: str) -> str:
        digits = word[len(prefix):]
        if not digits or not digits.isascii() or not digits.isdigit():
            raise self._error(f"不是合法的基础类型：{word!r}")
        if len(digits) > 1 and digits[0] == "0":
            raise self._error(f"类型宽度不允许前导零：{word!r}")
        return digits

    def _sized_integer(self, word: str) -> ElementaryType:
        if word.startswith("uint"):
            prefix, kind = "uint", "uint"
        else:
            prefix, kind = "int", "int"
        digits = self._digits_suffix(word, prefix)
        try:
            return ElementaryType(kind, bit_size=int(digits))
        except ABITypeError:
            # 规范化错误信息：重新抛出由本解析器生成的错误
            raise self._error(
                f"{kind} 的位宽必须是 8 到 256 之间 8 的倍数，得到 {digits}"
            ) from None

    def _sized_bytes(self, word: str) -> ElementaryType:
        digits = self._digits_suffix(word, "bytes")
        try:
            return ElementaryType("bytes", byte_size=int(digits))
        except ABITypeError:
            raise self._error(f"bytesM 的 M 必须在 1 到 32 之间，得到 {digits}") from None

    def _parse_tuple(self) -> TupleType:
        # 调用前当前字符为 '('；括号内侧不允许空白。
        self._pos += 1
        self._tuple_depth += 1
        # 语义嵌套上限由类型对象构造检查；此处仅在触及 Python 递归限制
        # 前拦截过深（或大量未闭合）的括号，保证唯一异常约定。
        if self._tuple_depth > _RECURSION_SAFETY_LIMIT:
            self._tuple_depth -= 1
            raise self._error("类型嵌套过深或括号未正确闭合")
        try:
            if self._peek() == ")":
                self._pos += 1
                return TupleType(())
            components: list[ABIType] = []
            while True:
                components.append(self._parse_type())
                # 逗号左侧允许 ASCII 空白；但 ')' 内侧不允许，因此先记录
                # 是否跳过了空白，若空白后直接是 ')' 则属非法。
                anchor = self._pos
                self._skip_whitespace()
                had_whitespace = self._pos != anchor
                ch = self._peek()
                if ch == ",":
                    self._pos += 1
                    # 逗号右侧允许 ASCII 空白。
                    self._skip_whitespace()
                    if self._peek() in (None, ",", ")"):
                        raise self._error("逗号后缺少类型")
                    continue
                if ch == ")":
                    if had_whitespace:
                        raise self._error("元组 ')' 内侧不允许空白")
                    self._pos += 1
                    return TupleType(tuple(components))
                raise self._error("元组中应为 ',' 或 ')'")
        finally:
            self._tuple_depth -= 1

    def _parse_suffixes(self, head: ABIType) -> ABIType:
        current = head
        while self._peek() == "[":
            self._pos += 1
            ch = self._peek()
            if ch is None:
                raise self._error("数组后缀不完整")
            if ch == "]":
                self._pos += 1
                current = ArrayType(current)
                continue
            # 定长数组：只接受 [1-9][0-9]*，拒绝 0 与前导零。
            if not (ch.isascii() and ch.isdigit()) or ch == "0":
                raise self._error("数组长度必须是无前导零的正整数")
            start = self._pos
            while True:
                ch = self._peek()
                if ch is not None and ch.isascii() and ch.isdigit():
                    self._pos += 1
                    continue
                break
            length = int(self._text[start:self._pos])
            if self._peek() != "]":
                raise self._error("数组后缀缺少 ']'")
            self._pos += 1
            current = ArrayType(current, length)
        return current


def parse_abi_type(type_string: str) -> ABIType:
    """解析 ABI 类型字符串，返回不可变类型对象。

    无效输入统一抛出 :class:`abi_kit.ABITypeError`。
    """
    if not isinstance(type_string, str):
        raise ABITypeError(f"ABI 类型必须是字符串，得到 {type(type_string).__name__}")
    if type_string == "":
        raise ABITypeError("无效的 ABI 类型 ''：类型为空")
    return _Parser(type_string).parse()

"""函数 ABI 解析、selector 与函数调用数据（calldata）编解码。

- :func:`parse_function_abi`：解析 ABI JSON 字符串或等价条目数组，只消费
  ``type == "function"`` 的条目，返回不可变 :class:`FunctionDefinition`；
  event / constructor / error / receive / fallback 条目跳过不解析。
- :func:`canonical_function_signature`：返回
  ``name(type1,type2,...)`` 形式的规范函数签名（参数名不参与）。
- :func:`function_selector`：返回
  ``keccak256(canonical_signature)[:4]`` 的四字节 selector。
- :func:`encode_function_call`：按函数名（无重载时）或规范签名选择函数，
  按公开参数顺序编码实参，返回 selector 与 ``selector + ABI(参数 tuple)``
  的完整 calldata。
- :func:`decode_function_call`：按 calldata 前四字节还原函数，再严格解码
  参数 tuple，返回函数标识、规范签名与带类型标注的参数结果。
- :func:`encode_function_result` / :func:`decode_function_result`：按
  函数 outputs 声明编解码返回值；outputs 不参与 selector 与 calldata，
  无 outputs 的函数编码为 ``b""``。

``encodeFunctionCall`` / ``decodeFunctionCall`` 与
``encodeFunctionResult`` / ``decodeFunctionResult`` 是上述入口的
camelCase 别名。

错误约定：

- 元数据非法（ABI 根不是数组、function 条目缺 name/type/inputs、
  标识符非法、参数类型字符串无法解析等）抛
  :class:`abi_kit.AbiMetadataError`；
- 函数名或规范签名无匹配抛 :class:`abi_kit.AbiFunctionNotFoundError`；
- 只给函数名但同名重载不止一个、无法唯一选择抛
  :class:`abi_kit.AbiOverloadError`；
- selector 匹配不到任何函数抛 :class:`abi_kit.AbiSelectorError`；
- calldata 少于四字节抛 :class:`abi_kit.AbiCalldataLengthError`；
- 实参不能按声明类型编码、或参数区不能按声明类型严格解码抛
  :class:`abi_kit.ABIValueError`；
- 参数消费完后仍有尾随字节抛 :class:`abi_kit.AbiTrailingDataError`；
- 返回值数量或类型与 outputs 声明不符、返回值数据不能严格解码抛
  :class:`abi_kit.ABIValueError`；返回值解码后仍有尾随字节同样抛
  :class:`abi_kit.AbiTrailingDataError`。
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field

from ._codec import _decode, _encode
from ._event import _build_type, _is_identifier
from ._exceptions import (
    AbiCalldataLengthError,
    AbiEventError,
    AbiFunctionNotFoundError,
    AbiMetadataError,
    AbiOverloadError,
    AbiSelectorError,
    AbiTrailingDataError,
    ABITypeError,
    ABIValueError,
)
from ._format import format_abi_type
from ._keccak import keccak_256
from ._types import ABIType, TupleType

_SELECTOR_LEN = 4

#: 函数路径跳过但允许保留在 ABI 中的非函数条目类型；这些条目的合法性
#: 由各自入口（如事件路径）负责，本模块不解析。
_NON_FUNCTION_ENTRY_TYPES = frozenset(
    ("event", "constructor", "error", "receive", "fallback")
)


# ---- 不可变定义与结果对象 -------------------------------------------------


@dataclass(frozen=True)
class FunctionParameter:
    """函数的单个公开参数（声明顺序保留）。

    - ``name``：ABI JSON 中的参数名，缺省为空串；
    - ``abi_type``：由 ``type`` + ``components`` 展开得到的类型对象。
    """

    name: str
    abi_type: ABIType


@dataclass(frozen=True)
class FunctionDefinition:
    """不可变函数定义。

    - ``name``：非空 ASCII 函数标识符；
    - ``inputs``：按声明顺序保存的 :class:`FunctionParameter`；
    - ``outputs``：按声明顺序保存的返回值 :class:`FunctionParameter`
      （缺省为空）；outputs 不参与规范签名、selector 与 calldata。
    """

    name: str
    inputs: tuple[FunctionParameter, ...] = field(default=())
    outputs: tuple[FunctionParameter, ...] = field(default=())


@dataclass(frozen=True)
class EncodedFunctionCall:
    """函数调用编码结果。

    - ``function``：命中的 :class:`FunctionDefinition`；
    - ``selector``：四字节 selector（bytes）；
    - ``calldata``：``selector + 参数 ABI 编码`` 的完整调用数据。
    """

    function: FunctionDefinition
    selector: bytes
    calldata: bytes

    @property
    def function_name(self) -> str:
        """命中函数的名称。"""
        return self.function.name

    @property
    def signature(self) -> str:
        """命中函数的规范签名，如 ``transfer(address,uint256)``。"""
        return canonical_function_signature(self.function)

    @property
    def selector_hex(self) -> str:
        """``"0x"`` + 8 个小写十六进制字符形式的 selector。"""
        return "0x" + self.selector.hex()

    @property
    def calldata_hex(self) -> str:
        """``"0x"`` 前缀的完整 calldata 十六进制字符串。"""
        return "0x" + self.calldata.hex()


@dataclass(frozen=True)
class FunctionArgument:
    """解码后带类型标注的单个实参。

    - ``name``：声明的参数名，未命名时为空串；
    - ``type``：规范 ABI 类型字符串（不含空白与参数名）；
    - ``value``：按值层口径还原的 Python 值。
    """

    name: str
    type: str
    value: object


@dataclass(frozen=True)
class DecodedFunctionCall:
    """函数调用解码结果。

    - ``function``：selector 命中的 :class:`FunctionDefinition`；
    - ``selector``：calldata 前四字节（bytes）；
    - ``args``：按声明顺序排列的 :class:`FunctionArgument`。
    """

    function: FunctionDefinition
    selector: bytes
    args: tuple[FunctionArgument, ...] = field(default=())

    @property
    def function_name(self) -> str:
        """命中函数的名称。"""
        return self.function.name

    @property
    def signature(self) -> str:
        """命中函数的规范签名，如 ``transfer(address,uint256)``。"""
        return canonical_function_signature(self.function)

    @property
    def selector_hex(self) -> str:
        """``"0x"`` + 8 个小写十六进制字符形式的 selector。"""
        return "0x" + self.selector.hex()

    @property
    def values(self) -> tuple:
        """按声明顺序去掉类型标注后的纯值 tuple。"""
        return tuple(arg.value for arg in self.args)


@dataclass(frozen=True)
class EncodedFunctionResult:
    """函数返回值编码结果。

    - ``function``：命中的 :class:`FunctionDefinition`；
    - ``data``：outputs tuple 的 ABI 编码，无 outputs 时为 ``b""``。
    """

    function: FunctionDefinition
    data: bytes

    @property
    def function_name(self) -> str:
        """命中函数的名称。"""
        return self.function.name

    @property
    def signature(self) -> str:
        """命中函数的规范签名（outputs 不参与），如 ``balanceOf(address)``。"""
        return canonical_function_signature(self.function)

    @property
    def data_hex(self) -> str:
        """``"0x"`` 前缀的小写十六进制编码结果。"""
        return "0x" + self.data.hex()


@dataclass(frozen=True)
class DecodedFunctionResult:
    """函数返回值解码结果。

    - ``function``：命中的 :class:`FunctionDefinition`；
    - ``outputs``：按声明顺序排列的 :class:`FunctionArgument`，``name``
      为声明的返回值名（未命名为空串），``type`` 为规范 ABI 类型字符串。
    """

    function: FunctionDefinition
    outputs: tuple[FunctionArgument, ...] = field(default=())

    @property
    def function_name(self) -> str:
        """命中函数的名称。"""
        return self.function.name

    @property
    def signature(self) -> str:
        """命中函数的规范签名（outputs 不参与），如 ``balanceOf(address)``。"""
        return canonical_function_signature(self.function)

    @property
    def values(self) -> tuple:
        """按声明顺序去掉类型标注后的纯值 tuple。"""
        return tuple(output.value for output in self.outputs)


# ---- ABI 解析 -------------------------------------------------------------


def _metadata(message: str) -> AbiMetadataError:
    return AbiMetadataError(message)


def _parse_parameters(name: str, nodes, noun: str) -> tuple[FunctionParameter, ...]:
    """把 inputs/outputs 节点数组展开为 :class:`FunctionParameter` tuple。"""
    parameters: list[FunctionParameter] = []
    for node in nodes:
        if not isinstance(node, dict):
            raise _metadata(
                f"函数 {name!r} 的{noun}必须是 JSON 对象，得到 {type(node).__name__}"
            )
        param_name = node.get("name", "")
        if not isinstance(param_name, str):
            raise _metadata(
                f"函数 {name!r} 的{noun} name 必须是字符串，得到 {param_name!r}"
            )
        try:
            # 与事件路径共用同一套 type + components 递归展开；其失败
            # 统一是事件层错误码，这里转译为函数元数据错误。
            abi_type = _build_type(node)
        except (AbiEventError, ABITypeError) as exc:
            raise _metadata(f"函数 {name!r} 的{noun}类型非法：{exc}") from None
        parameters.append(FunctionParameter(param_name, abi_type))
    return tuple(parameters)


def _parse_function_entry(entry: dict) -> FunctionDefinition:
    """从单个 ABI function 条目构造不可变函数定义。"""
    name = entry.get("name")
    if not _is_identifier(name):
        raise _metadata(f"函数 name 必须是非空 ASCII 标识符，得到 {name!r}")
    if "inputs" not in entry:
        raise _metadata(f"函数 {name!r} 缺少 inputs")
    inputs_node = entry["inputs"]
    if not isinstance(inputs_node, (list, tuple)):
        raise _metadata(f"函数 {name!r} 的 inputs 必须是数组")
    inputs = _parse_parameters(name, inputs_node, "参数")

    # outputs 缺省视为无返回值；存在时必须是合法参数描述数组。
    outputs_node = entry.get("outputs", [])
    if not isinstance(outputs_node, (list, tuple)):
        raise _metadata(f"函数 {name!r} 的 outputs 必须是数组")
    outputs = _parse_parameters(name, outputs_node, "返回值")

    return FunctionDefinition(name, inputs, outputs)


def parse_function_abi(abi) -> tuple[FunctionDefinition, ...]:
    """解析 ABI，返回其中全部 function 条目的不可变定义。

    ``abi`` 接受 ABI JSON 字符串（:func:`json.loads` 口径）或等价的
    Python 条目数组（list/tuple）。只消费 ``type == "function"`` 的条目；
    event、constructor、error、receive、fallback 等其他条目原样保留在
    ABI 中但不解析、不影响函数路径。函数条目的 ``inputs`` 必填，
    ``outputs`` 缺省视为无返回值。任何函数元数据非法抛
    :class:`abi_kit.AbiMetadataError`。
    """
    if isinstance(abi, str):
        try:
            root = json.loads(abi)
        except (json.JSONDecodeError, ValueError) as exc:
            raise _metadata(f"ABI JSON 解析失败：{exc}") from None
    elif isinstance(abi, (list, tuple)):
        root = abi
    else:
        raise _metadata(
            f"ABI 必须是 JSON 字符串或条目数组，得到 {type(abi).__name__}"
        )

    if not isinstance(root, (list, tuple)):
        raise _metadata("ABI 必须是条目数组，JSON 根不能是对象或标量")

    functions: list[FunctionDefinition] = []
    for entry in root:
        if not isinstance(entry, dict):
            raise _metadata(
                f"ABI 条目必须是 JSON 对象，得到 {type(entry).__name__}"
            )
        entry_type = entry.get("type")
        # event/constructor/error/receive/fallback 条目保留在 ABI 中供
        # 各自入口使用，函数路径跳过且不校验；缺 type 或未知条目类型属
        # 元数据非法，统一抛 AbiMetadataError。
        if entry_type == "function":
            functions.append(_parse_function_entry(entry))
        elif entry_type in _NON_FUNCTION_ENTRY_TYPES:
            continue
        else:
            raise _metadata(
                f"ABI 条目缺少 type 或带有未知类型 {entry_type!r}，"
                "合法值为 function/event/constructor/error/receive/fallback"
            )
    return tuple(functions)


# ---- 规范签名与 selector --------------------------------------------------


def canonical_function_signature(function: FunctionDefinition) -> str:
    """返回规范函数签名 ``name(type1,type2,...)``。

    参数名不参与签名；tuple 输出为 ``(t1,t2)``，数组保留 ``[]``/``[n]``
    后缀。
    """
    if not isinstance(function, FunctionDefinition):
        raise _metadata(
            f"需要 FunctionDefinition，得到 {type(function).__name__}"
        )
    canonical = ",".join(format_abi_type(p.abi_type) for p in function.inputs)
    return f"{function.name}({canonical})"


def function_selector(function: FunctionDefinition) -> bytes:
    """返回函数四字节 selector：``keccak256(规范签名)[:4]``。"""
    signature = canonical_function_signature(function)
    try:
        digest = keccak_256(signature.encode("utf-8"))
    except (TypeError, ValueError) as exc:
        raise _metadata(f"规范签名无法生成 selector：{exc}") from None
    return digest[:_SELECTOR_LEN]


# ---- 选择函数 -------------------------------------------------------------


def _resolve_function(
    functions: tuple[FunctionDefinition, ...], key
) -> FunctionDefinition:
    """按函数名或规范签名在已解析函数中唯一定位。"""
    if not isinstance(key, str) or not key:
        raise _metadata(f"函数名或规范签名必须是非空字符串，得到 {key!r}")

    if "(" in key or ")" in key:
        for function in functions:
            if canonical_function_signature(function) == key:
                return function
        raise AbiFunctionNotFoundError(
            f"ABI 中找不到规范签名为 {key!r} 的函数"
        )

    if not _is_identifier(key):
        raise _metadata(f"非法函数名：{key!r}")

    candidates = [function for function in functions if function.name == key]
    if not candidates:
        raise AbiFunctionNotFoundError(f"ABI 中找不到函数 {key!r}")
    if len(candidates) > 1:
        signatures = ", ".join(
            canonical_function_signature(function) for function in candidates
        )
        raise AbiOverloadError(
            f"函数 {key!r} 存在 {len(candidates)} 个重载，无法唯一选择，"
            f"请改用规范签名之一：{signatures}"
        )
    return candidates[0]


# ---- calldata 编解码 ------------------------------------------------------


def _coerce_calldata(calldata) -> bytes:
    """把 bytes 或可选 0x 前缀的十六进制字符串规范化为 bytes。"""
    if isinstance(calldata, bytes):
        return calldata
    if isinstance(calldata, str):
        text = calldata[2:] if calldata[:2] in ("0x", "0X") else calldata
        try:
            return bytes.fromhex(text)
        except ValueError as exc:
            raise ABIValueError(f"calldata 十六进制非法：{exc}") from exc
    raise ABIValueError(
        f"calldata 必须是 bytes 或十六进制 str，得到 {type(calldata).__name__}"
    )


def encode_function_call(
    abi, function_name, args=None
) -> EncodedFunctionCall:
    """编码一次函数调用。

    ``abi`` 接受 ABI JSON 字符串或等价条目数组；``function_name`` 接受
    函数名（ABI 中无同名重载时）或规范函数签名
    （``transfer(address,uint256)``）；``args`` 为按公开参数顺序排列的
    实参列表（list/tuple），无参函数可省略。

    返回 :class:`EncodedFunctionCall`，其中 ``selector`` 为四字节
    bytes，``calldata`` 为 ``selector + 参数 tuple 的 ABI 编码``。
    实参不能按声明类型编码（含数量不符）抛 :class:`abi_kit.ABIValueError`。
    """
    functions = parse_function_abi(abi)
    function = _resolve_function(functions, function_name)

    if args is None:
        values = ()
    elif isinstance(args, (list, tuple)):
        values = tuple(args)
    else:
        raise ABIValueError(
            f"实参列表必须是 list 或 tuple，得到 {type(args).__name__}"
        )

    parameter_types = TupleType(
        tuple(parameter.abi_type for parameter in function.inputs)
    )
    payload = _encode(parameter_types, values)
    selector = function_selector(function)
    return EncodedFunctionCall(function, selector, selector + payload)


def decode_function_call(abi, calldata) -> DecodedFunctionCall:
    """解码完整函数调用数据。

    ``calldata`` 接受 bytes 或可选 ``0x`` 前缀的十六进制字符串，前四字节
    必须是 ABI 中某个函数的 selector；其后按该函数公开参数组成的 tuple
    严格 ABI 解码。返回 :class:`DecodedFunctionCall`，携带函数定义、
    selector、规范签名（属性）与按声明顺序排列的带类型标注实参。

    calldata 少于四字节抛 :class:`abi_kit.AbiCalldataLengthError`；
    selector 无匹配抛 :class:`abi_kit.AbiSelectorError`；参数区不能严格
    解码抛 :class:`abi_kit.ABIValueError`；解码后仍有尾随字节抛
    :class:`abi_kit.AbiTrailingDataError`。
    """
    functions = parse_function_abi(abi)
    raw = _coerce_calldata(calldata)

    if len(raw) < _SELECTOR_LEN:
        raise AbiCalldataLengthError(
            f"calldata 长度必须至少为 {_SELECTOR_LEN} 字节以容纳 selector，"
            f"得到 {len(raw)} 字节"
        )
    selector = raw[:_SELECTOR_LEN]

    matches = [
        function
        for function in functions
        if function_selector(function) == selector
    ]
    if not matches:
        raise AbiSelectorError(
            f"selector 0x{selector.hex()} 在 ABI 中匹配不到任何函数"
        )
    function = matches[0]

    parameter_types = TupleType(
        tuple(parameter.abi_type for parameter in function.inputs)
    )
    payload = raw[_SELECTOR_LEN:]
    bound = len(payload)
    try:
        values, end = _decode(parameter_types, payload, 0, bound)
    except ABIValueError:
        raise
    if end != bound:
        raise AbiTrailingDataError(
            f"参数解码完成后仍有 {bound - end} 字节尾随数据未被消费"
        )

    arguments = tuple(
        FunctionArgument(
            parameter.name, format_abi_type(parameter.abi_type), value
        )
        for parameter, value in zip(function.inputs, values)
    )
    return DecodedFunctionCall(function, selector, arguments)


# camelCase 公开别名。
encodeFunctionCall = encode_function_call
decodeFunctionCall = decode_function_call


# ---- 返回值（outputs）编解码 ----------------------------------------------


_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")


def _coerce_result_data(data) -> bytes:
    """把 bytes 或可选 0x 前缀的偶数位十六进制字符串规范化为 bytes。"""
    if isinstance(data, bytes):
        return data
    if isinstance(data, str):
        text = data[2:] if data[:2] in ("0x", "0X") else data
        if len(text) % 2 or any(c not in _HEX_DIGITS for c in text):
            raise ABIValueError(
                "返回值数据必须是可选 0x 前缀的偶数位十六进制字符串"
            )
        return bytes.fromhex(text)
    raise ABIValueError(
        f"返回值数据必须是 bytes 或十六进制 str，得到 {type(data).__name__}"
    )


def _output_types(function: FunctionDefinition) -> TupleType:
    return TupleType(tuple(output.abi_type for output in function.outputs))


def encode_function_result(
    abi, function_name, values=None
) -> EncodedFunctionResult:
    """按函数 outputs 声明编码返回值。

    ``abi`` 接受 ABI JSON 字符串或等价条目数组；``function_name`` 接受
    函数名（ABI 中无同名重载时）或规范函数签名；``values`` 为按 outputs
    声明顺序排列的返回值列表（list/tuple），无 outputs 的函数只接受空
    序列（或可省略），编码结果为 ``b""``。

    返回 :class:`EncodedFunctionResult`，其中 ``data`` 为 outputs tuple
    的标准 ABI 编码，``data_hex`` 为其小写 ``"0x"`` 前缀十六进制形式。
    数量或类型与 outputs 声明不符抛 :class:`abi_kit.ABIValueError`。
    """
    functions = parse_function_abi(abi)
    function = _resolve_function(functions, function_name)

    if values is None:
        items = ()
    elif isinstance(values, (list, tuple)):
        items = tuple(values)
    else:
        raise ABIValueError(
            f"返回值列表必须是 list 或 tuple，得到 {type(values).__name__}"
        )

    data = _encode(_output_types(function), items)
    return EncodedFunctionResult(function, data)


def decode_function_result(abi, function_name, data) -> DecodedFunctionResult:
    """按函数 outputs 声明严格解码返回值数据。

    ``abi`` 与 ``function_name`` 口径同 :func:`encode_function_result`；
    ``data`` 接受 bytes 或可选 ``0x`` 前缀的偶数位十六进制字符串，按该
    函数 outputs 组成的 tuple 严格 ABI 解码。返回
    :class:`DecodedFunctionResult`，携带函数定义与按声明顺序排列的带
    类型标注返回值；``values`` 属性给出等价的纯值 tuple。无 outputs 的
    函数只接受 ``b""``，往返得到空 tuple。

    输入类型或十六进制非法、长度不足及 head/tail、偏移、长度、补零、
    UTF-8、定长数组约束不满足抛 :class:`abi_kit.ABIValueError`；解码后
    仍有尾随字节抛 :class:`abi_kit.AbiTrailingDataError`。
    """
    functions = parse_function_abi(abi)
    function = _resolve_function(functions, function_name)
    raw = _coerce_result_data(data)

    bound = len(raw)
    values, end = _decode(_output_types(function), raw, 0, bound)
    if end != bound:
        raise AbiTrailingDataError(
            f"返回值解码完成后仍有 {bound - end} 字节尾随数据未被消费"
        )

    outputs = tuple(
        FunctionArgument(output.name, format_abi_type(output.abi_type), value)
        for output, value in zip(function.outputs, values)
    )
    return DecodedFunctionResult(function, outputs)


# camelCase 公开别名。
encodeFunctionResult = encode_function_result
decodeFunctionResult = decode_function_result

"""事件 ABI 解析、签名 topic0 与日志还原。

- :func:`parse_event_abi`：解析 ABI JSON 的 event 对象，返回不可变的
  :class:`EventDefinition`，保留声明顺序与名称、indexed、anonymous 等
  声明元数据；tuple 参数由 ``components`` 递归展开。
- :func:`event_topic0`：按事件名与参数的规范 ABI 类型计算
  ``keccak256("Name(type1,type2,...)")``，返回小写 ``"0x"`` + 64 位
  十六进制；参数名与 indexed 不参与签名，anonymous 事件返回 None。
- :func:`decode_event_log`：校验 topics 并严格还原 data，按声明顺序
  合并为一个 tuple。
- :func:`encode_event_log`：按声明值生成日志 topics 与 data，返回不可变
  :class:`EncodedEventLog`，与 :func:`decode_event_log` 的 topics 数量、
  补零方向与 data tuple 口径一致。
- :func:`match_event_log_values`：在 :func:`decode_event_log` 校验通过
  的前提下，核验一组按声明顺序给出的候选值是否与日志一致，命中返回
  声明顺序 tuple，否则返回 None。

日志口径：

- 非 indexed 参数由 data 按 tuple 严格 ABI 解码，值口径与
  :func:`decode_abi_value` 完全一致；没有非 indexed 参数时 data 必须
  为空。
- indexed 的 address/bool/intM/uintM/bytesM 从各自 32 字节 topic 严格
  解码；indexed 的 string、动态 bytes、数组与 tuple 不可逆，原样返回
  32 字节 topic，口径为 bytes。

编码口径（encode_event_log）：

- 非 indexed 参数组成 tuple，按 :func:`encode_abi_value` 的 ABI 值编码
  生成 data；没有非 indexed 参数时 data 为空字节串。
- 非匿名事件 topics 首项为签名 topic0 的 32 字节，匿名事件不放；其后按
  声明顺序放置 indexed 主题，topics 总数与解码口径一致。
- indexed 的 address/bool/intM/uintM/bytesM 直接生成 32 字节 ABI 规范
  字（address 左补零、bytesM 右补零，与解码补零方向一致）；indexed 的
  string、动态 bytes、数组与 tuple 取事件索引特殊编码的 Keccak-256
  主题——string 用 UTF-8 字节、动态 bytes 用内容、数组省略长度递归连接
  元素、tuple 递归连接成员；基础值用 32 字节规范字（bytesM 右补零），
  递归成员与整段结果右补齐到 32 字节倍数，string 与动态 bytes 内容不
  补零。

候选值核验口径（match_event_log_values）：

- 先按 :func:`decode_event_log` 完成主题数量、topic0、topic 基础值与
  data 的全部严格校验，失败沿用其错误码；
- values 按声明顺序接受 list 或 tuple，数量不符或非序列抛
  EVENT_VALUE_INVALID；非 indexed 与可还原 indexed 基础值候选直接与
  解码值比较；
- indexed 的 string、动态 bytes、数组与 tuple 按上面的事件索引特殊编码
  重算 32 字节主题与日志 topic 比较，候选不能编码为其声明类型时抛
  EVENT_VALUE_INVALID；
- 全部一致返回声明顺序 tuple，任一值或哈希不同只返回 None。

所有失败统一抛出 :class:`abi_kit.AbiEventError`，以 ``code`` 区分。
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field

from ._codec import _encode, decode_abi_value
from ._exceptions import ABITypeError, ABIValueError, AbiEventError
from ._format import format_abi_type
from ._keccak import keccak_256
from ._parser import parse_abi_type
from ._types import ABIType, ArrayType, ElementaryType, TupleType

_WORD = 32
_HEX_DIGITS = set("0123456789abcdefABCDEF")
_SUFFIX_RE = re.compile(r"^(\[\d*\])*$")
_SUFFIX_PART = re.compile(r"\[(\d*)\]")

#: components 递归展开的安全上限，与类型解析器一致：语义嵌套上限
#: （128 层）由类型对象构造时检查；此阈值仅用于在触及 Python 递归限制
#: 前抛出 EVENT_ABI_INVALID。
_RECURSION_SAFETY_LIMIT = 200


@dataclass(frozen=True)
class EventParameter:
    """事件的单个参数（声明顺序保留）。

    - ``name``：ABI JSON 中的参数名，缺省为空串；
    - ``abi_type``：由 ``type`` + ``components`` 展开得到的类型对象；
    - ``indexed``：是否进入 topics。
    """

    name: str
    abi_type: ABIType
    indexed: bool = False


@dataclass(frozen=True)
class EventDefinition:
    """不可变事件定义。

    - ``name``：非空 ASCII 事件标识符；
    - ``inputs``：按声明顺序保存的 :class:`EventParameter`；
    - ``anonymous``：是否为匿名事件（缺省视为 False）。
    """

    name: str
    inputs: tuple[EventParameter, ...] = field(default=())
    anonymous: bool = False


@dataclass(frozen=True)
class EncodedEventLog:
    """不可变事件日志编码结果。

    - ``event``：对应的 :class:`EventDefinition`；
    - ``topics``：bytes tuple——非匿名事件首项为签名 topic0 的 32 字节，
      其后按声明顺序排列 indexed 主题；
    - ``data``：非 indexed 参数 tuple 的 ABI 值编码，无非 indexed 参数
      时为空字节串；
    - ``topics_hex`` / ``data_hex``：对应的 ``"0x"`` 小写十六进制形式。
    """

    event: EventDefinition
    topics: tuple[bytes, ...] = field(default=())
    data: bytes = b""

    @property
    def topics_hex(self) -> tuple[str, ...]:
        """各项 topics 的 ``"0x"`` + 64 位小写十六进制 tuple。"""
        return tuple("0x" + topic.hex() for topic in self.topics)

    @property
    def data_hex(self) -> str:
        """``data`` 的 ``"0x"`` 前缀小写十六进制字符串。"""
        return "0x" + self.data.hex()


# ---- ABI JSON 解析 -------------------------------------------------------


def _invalid(message: str) -> AbiEventError:
    return AbiEventError("EVENT_ABI_INVALID", message)


def _is_identifier(name) -> bool:
    if not isinstance(name, str) or not name or not name.isascii():
        return False
    first, rest = name[0], name[1:]
    if not (first.isalpha() or first in "_$"):
        return False
    return all(ch.isalnum() or ch in "_$" for ch in rest)


def _apply_suffixes(inner: ABIType, suffix: str) -> ABIType:
    """把 ``"[]"`` / ``"[n]"`` 后缀序列依次套到 inner 外层。"""
    current = inner
    for match in _SUFFIX_PART.finditer(suffix):
        digits = match.group(1)
        if digits:
            # 与类型解析器一致：拒绝 0 长度与前导零。
            if digits[0] == "0":
                raise _invalid(f"数组长度必须是无前导零的正整数：[{digits}]")
            current = ArrayType(current, int(digits))
        else:
            current = ArrayType(current)
    return current


def _build_type(node, depth: int = 1) -> ABIType:
    """从一个 ABI 参数 JSON 节点递归构造类型对象。"""
    if depth > _RECURSION_SAFETY_LIMIT:
        raise _invalid("components 嵌套过深")
    if not isinstance(node, dict):
        raise _invalid(f"参数描述必须是 JSON 对象，得到 {type(node).__name__}")
    type_string = node.get("type")
    if not isinstance(type_string, str) or not type_string:
        raise _invalid(f"参数必须带有非空字符串 type，得到 {type_string!r}")

    if type_string == "tuple" or type_string.startswith("tuple["):
        suffix = type_string[len("tuple"):]
        if not _SUFFIX_RE.match(suffix):
            raise _invalid(f"非法 tuple 类型字符串：{type_string!r}")
        components_node = node.get("components")
        if not isinstance(components_node, list):
            raise _invalid(
                f"tuple 参数必须带有列表形式的 components：{type_string!r}"
            )
        component_types: list[ABIType] = []
        component_names: list[str | None] = []
        for component in components_node:
            component_types.append(_build_type(component, depth + 1))
            if isinstance(component, dict) and isinstance(component.get("name"), str):
                component_names.append(component["name"] or None)
            else:
                component_names.append(None)
        try:
            current: ABIType = TupleType(
                tuple(component_types), names=tuple(component_names)
            )
            if suffix:
                current = _apply_suffixes(current, suffix)
        except ABITypeError as exc:
            raise _invalid(f"tuple 类型构造失败：{exc}") from None
        return current

    if "components" in node:
        raise _invalid(f"非 tuple 参数不能带有 components：{type_string!r}")
    try:
        return parse_abi_type(type_string)
    except ABITypeError as exc:
        raise _invalid(f"参数类型 {type_string!r} 非法：{exc}") from None


def _build_inputs(event_json: dict) -> tuple[EventParameter, ...]:
    inputs_node = event_json.get("inputs", [])
    if not isinstance(inputs_node, list):
        raise _invalid("事件 inputs 必须是数组")
    inputs: list[EventParameter] = []
    for node in inputs_node:
        if not isinstance(node, dict):
            raise _invalid(f"事件参数必须是 JSON 对象，得到 {type(node).__name__}")
        name = node.get("name", "")
        if not isinstance(name, str):
            raise _invalid(f"事件参数 name 必须是字符串，得到 {name!r}")
        indexed = node.get("indexed", False)
        if not isinstance(indexed, bool):
            raise _invalid(f"indexed 必须是布尔值，得到 {indexed!r}")
        inputs.append(EventParameter(name, _build_type(node), indexed))
    return tuple(inputs)


def parse_event_abi(event_json: dict) -> EventDefinition:
    """解析 ABI JSON 的 event 对象，返回不可变 :class:`EventDefinition`。

    要求 ``type == "event"``、``name`` 为非空 ASCII 标识符；布尔标志
    缺失视为 False；tuple 参数由 ``components`` 递归展开。任何非法输入
    抛出带 ``EVENT_ABI_INVALID`` 的 :class:`abi_kit.AbiEventError`。
    """
    if not isinstance(event_json, dict):
        raise _invalid(
            f"事件描述必须是 JSON 对象，得到 {type(event_json).__name__}"
        )
    if event_json.get("type") != "event":
        raise _invalid(f"type 必须为 \"event\"，得到 {event_json.get('type')!r}")
    name = event_json.get("name")
    if not _is_identifier(name):
        raise _invalid(f"事件 name 必须是非空 ASCII 标识符，得到 {name!r}")
    anonymous = event_json.get("anonymous", False)
    if not isinstance(anonymous, bool):
        raise _invalid(f"anonymous 必须是布尔值，得到 {anonymous!r}")
    return EventDefinition(name, _build_inputs(event_json), anonymous)


# ---- topic0 --------------------------------------------------------------


def _event_signature(event: EventDefinition) -> str:
    canonical = ",".join(format_abi_type(param.abi_type) for param in event.inputs)
    return f"{event.name}({canonical})"


def event_topic0(event: EventDefinition) -> str | None:
    """计算事件签名 topic0。

    返回小写 ``"0x"`` + 64 位十六进制；anonymous 事件返回 None。
    参数名与 indexed 不参与签名。
    """
    if not isinstance(event, EventDefinition):
        raise _invalid(
            f"需要 EventDefinition，得到 {type(event).__name__}"
        )
    if event.anonymous:
        return None
    digest = keccak_256(_event_signature(event).encode("utf-8"))
    return "0x" + digest.hex()


# ---- 日志还原 ------------------------------------------------------------


def _error(code: str, message: str) -> AbiEventError:
    return AbiEventError(code, message)


def _topic_bytes(item) -> bytes:
    """把单个 topic 规范化为 32 字节，失败抛 EVENT_TOPIC_VALUE。"""
    if isinstance(item, bytes):
        if len(item) != _WORD:
            raise _error(
                "EVENT_TOPIC_VALUE",
                f"topic 必须是 32 字节，得到 {len(item)} 字节",
            )
        return item
    if isinstance(item, str):
        text = item[2:] if item.startswith(("0x", "0X")) else item
        if len(text) != 64 or any(c not in _HEX_DIGITS for c in text):
            raise _error(
                "EVENT_TOPIC_VALUE",
                "topic 必须是可选 0x 前缀的 64 位十六进制字符串",
            )
        return bytes.fromhex(text)
    raise _error(
        "EVENT_TOPIC_VALUE",
        f"topic 必须是 bytes 或十六进制字符串，得到 {type(item).__name__}",
    )


def _data_bytes(data) -> bytes:
    """把 data 规范化为字节串，失败抛 EVENT_DATA_INVALID。"""
    if isinstance(data, bytes):
        return data
    if isinstance(data, str):
        text = data[2:] if data.startswith(("0x", "0X")) else data
        if len(text) % 2 or any(c not in _HEX_DIGITS for c in text):
            raise _error(
                "EVENT_DATA_INVALID",
                "data 必须是可选 0x 前缀的偶数位十六进制字符串",
            )
        return bytes.fromhex(text)
    raise _error(
        "EVENT_DATA_INVALID",
        f"data 必须是 bytes 或十六进制字符串，得到 {type(data).__name__}",
    )


def _decode_indexed(abi_type: ABIType, topic: bytes):
    """从 32 字节 topic 严格解码可还原的 indexed 基础值。"""
    if isinstance(abi_type, ArrayType) or isinstance(abi_type, TupleType):
        return topic
    if not isinstance(abi_type, ElementaryType):
        return topic
    kind = abi_type.kind
    if kind == "string" or (kind == "bytes" and abi_type.byte_size is None):
        return topic
    if kind == "address":
        if topic[:12] != b"\x00" * 12:
            raise _error("EVENT_TOPIC_VALUE", "address topic 高位 12 字节非零")
        return "0x" + topic[12:].hex()
    if kind == "bool":
        if topic == b"\x00" * _WORD:
            return False
        if topic == b"\x00" * (_WORD - 1) + b"\x01":
            return True
        raise _error("EVENT_TOPIC_VALUE", "bool topic 既非全 0 也非末尾字节为 1")
    if kind == "uint":
        value = int.from_bytes(topic, "big", signed=False)
        if value >= 1 << abi_type.bit_size:
            raise _error(
                "EVENT_TOPIC_VALUE",
                f"uint{abi_type.bit_size} topic 解码值越界：{value}",
            )
        return value
    if kind == "int":
        value = int.from_bytes(topic, "big", signed=True)
        bits = abi_type.bit_size
        low = -(1 << (bits - 1))
        high = (1 << (bits - 1)) - 1
        if not low <= value <= high:
            raise _error(
                "EVENT_TOPIC_VALUE",
                f"int{bits} topic 解码值超出补码范围：{value}",
            )
        return value
    # bytesM
    if topic[abi_type.byte_size:] != b"\x00" * (_WORD - abi_type.byte_size):
        raise _error(
            "EVENT_TOPIC_VALUE",
            f"bytes{abi_type.byte_size} topic 尾部填充非零",
        )
    return topic[:abi_type.byte_size]


def decode_event_log(event: EventDefinition, topics, data) -> tuple:
    """校验日志并还原事件参数。

    非匿名事件的 topics 必须以正确 topic0 开头，总数为 indexed 参数数
    加一；匿名事件总数等于 indexed 参数数。data 必须能按非 indexed
    参数组成的 tuple 严格解码，无此类参数时必须为空。返回值按参数声明
    顺序合并为一个 tuple。任何失败抛 :class:`abi_kit.AbiEventError`。
    """
    if not isinstance(event, EventDefinition):
        raise _invalid(f"需要 EventDefinition，得到 {type(event).__name__}")
    if isinstance(topics, (str, bytes)) or not isinstance(topics, (list, tuple)):
        raise _error(
            "EVENT_TOPIC_VALUE",
            f"topics 必须是列表或元组，得到 {type(topics).__name__}",
        )

    indexed_params = [param for param in event.inputs if param.indexed]
    indexed_count = len(indexed_params)
    expected = indexed_count if event.anonymous else indexed_count + 1
    if len(topics) != expected:
        raise _error(
            "EVENT_TOPIC_COUNT",
            f"topics 数量应为 {expected}，得到 {len(topics)}",
        )

    normalized_topics = [_topic_bytes(item) for item in topics]
    if not event.anonymous:
        expected_topic0 = bytes.fromhex(event_topic0(event)[2:])
        if normalized_topics[0] != expected_topic0:
            raise _error(
                "EVENT_TOPIC0_MISMATCH",
                "topics[0] 与事件签名 topic0 不一致",
            )

    payload = _data_bytes(data)
    non_indexed = [param for param in event.inputs if not param.indexed]
    if non_indexed:
        data_type = TupleType(tuple(param.abi_type for param in non_indexed))
        try:
            decoded_data = decode_abi_value(data_type, payload)
        except ValueError as exc:
            # decode_abi_value 对严格布局的任何违反都抛 ValueError；
            # 统一为日志层错误码 EVENT_DATA_INVALID。
            raise _error("EVENT_DATA_INVALID", f"非 indexed 参数解码失败：{exc}") from None
    else:
        if payload:
            raise _error(
                "EVENT_DATA_INVALID",
                f"事件无非 indexed 参数，但 data 含有 {len(payload)} 字节",
            )
        decoded_data = ()

    result = []
    indexed_iter = iter(normalized_topics if event.anonymous else normalized_topics[1:])
    data_iter = iter(decoded_data)
    for param in event.inputs:
        if param.indexed:
            result.append(_decode_indexed(param.abi_type, next(indexed_iter)))
        else:
            result.append(next(data_iter))
    return tuple(result)


# ---- 日志编码 ------------------------------------------------------------


def _value_invalid(message: str) -> AbiEventError:
    return AbiEventError("EVENT_VALUE_INVALID", message)


def _word_pad(payload: bytes) -> bytes:
    """把内容右补齐到 32 字节倍数（已对齐时原样返回）。"""
    return payload + b"\x00" * (-len(payload) % _WORD)


def _indexed_preimage(abi_type: ABIType, value) -> bytes:
    """构造动态 indexed 值的事件索引特殊编码原像（尚未 Keccak）。

    - string：UTF-8 字节，不补零；动态 bytes：原始内容，不补零；
    - 其余基础类型：32 字节 ABI 规范字（bytesM 右补零）；
    - 数组：省略长度字，递归连接各元素，每个元素各自右补齐到 32 字节
      倍数；
    - tuple：递归连接各成员，每个成员各自右补齐到 32 字节倍数。

    值口径与 :func:`encode_abi_value` 完全一致，任何不匹配抛
    :class:`abi_kit.ABIValueError`。
    """
    if isinstance(abi_type, ElementaryType):
        kind = abi_type.kind
        if kind == "string":
            if not isinstance(value, str):
                raise ABIValueError(
                    f"string 需要 str，得到 {type(value).__name__}"
                )
            try:
                return value.encode("utf-8")
            except UnicodeEncodeError as exc:
                raise ABIValueError(f"字符串无法编码为 UTF-8：{exc}") from exc
        if kind == "bytes" and abi_type.byte_size is None:
            if not isinstance(value, bytes):
                raise ABIValueError(
                    f"bytes 需要 bytes，得到 {type(value).__name__}"
                )
            return value
        # 静态基础类型（address/bool/intM/uintM/bytesM）的规范字。
        return _encode(abi_type, value)
    if isinstance(abi_type, ArrayType):
        if not isinstance(value, list):
            raise ABIValueError(f"数组需要 list，得到 {type(value).__name__}")
        if abi_type.length is not None and len(value) != abi_type.length:
            raise ABIValueError(
                f"定长数组长度应为 {abi_type.length}，得到 {len(value)}"
            )
        # 省略数组长度字，递归连接元素；元素按 32 字节倍数右补齐。
        pieces = [
            _word_pad(_indexed_preimage(abi_type.element_type, item))
            for item in value
        ]
        return _word_pad(b"".join(pieces))
    if isinstance(abi_type, TupleType):
        if not isinstance(value, tuple):
            raise ABIValueError(f"元组需要 tuple，得到 {type(value).__name__}")
        if len(value) != len(abi_type.components):
            raise ABIValueError(
                f"元组长度应为 {len(abi_type.components)}，得到 {len(value)}"
            )
        # 递归连接成员；成员按 32 字节倍数右补齐。
        pieces = [
            _word_pad(_indexed_preimage(member_type, member_value))
            for member_type, member_value in zip(abi_type.components, value)
        ]
        return _word_pad(b"".join(pieces))
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


def _encode_indexed_topic(abi_type: ABIType, value) -> bytes:
    """把单个 indexed 值编码为 32 字节主题。"""
    if isinstance(abi_type, ElementaryType):
        kind = abi_type.kind
        is_dynamic_bytes = kind == "bytes" and abi_type.byte_size is None
        if kind != "string" and not is_dynamic_bytes:
            # address/bool/intM/uintM/bytesM 直接用 ABI 规范字，补零方向
            # 与 _decode_indexed 一致（address 左补零、bytesM 右补零）。
            return _encode(abi_type, value)
    # string、动态 bytes、数组（含定长数组）与 tuple 取 Keccak-256 主题。
    return keccak_256(_indexed_preimage(abi_type, value))


def _is_hashed_indexed_type(abi_type: ABIType) -> bool:
    """该 indexed 类型是否走事件索引特殊编码（Keccak-256 主题）。

    与 :func:`_encode_indexed_topic` 的分支保持一致：string、动态 bytes、
    数组（含定长数组）与 tuple 取哈希主题；address/bool/intM/uintM/bytesM
    直接生成可还原的 32 字节规范字。
    """
    if isinstance(abi_type, ElementaryType):
        return abi_type.kind == "string" or (
            abi_type.kind == "bytes" and abi_type.byte_size is None
        )
    return isinstance(abi_type, (ArrayType, TupleType))


def encode_event_log(event: EventDefinition, values) -> EncodedEventLog:
    """按声明值编码事件日志，返回不可变 :class:`EncodedEventLog`。

    ``values`` 按参数声明顺序排列，接受 list 或 tuple，数量必须与事件
    参数数相等。非 indexed 参数组成 tuple 按 ABI 值编码生成 data，无非
    indexed 参数时 data 为 ``b""``；非匿名事件 topics 首项为签名
    topic0 的 32 字节，匿名事件不放，其后按声明顺序放置 indexed 主题，
    数量口径与 :func:`decode_event_log` 一致。

    indexed 的 address/bool/intM/uintM/bytesM 生成 32 字节 ABI 规范字；
    indexed 的 string、动态 bytes、数组与 tuple 生成事件索引特殊编码的
    Keccak-256 主题。相同输入始终得到相同结果。

    event 不是 :class:`EventDefinition`、values 不是 list/tuple、数量
    不符或任一值与其声明类型不匹配时，统一抛
    :class:`abi_kit.AbiEventError`（code 为 ``EVENT_VALUE_INVALID``）；
    :class:`abi_kit.ABIValueError` 与 :class:`abi_kit.ABITypeError` 不会
    泄漏到本入口之外。
    """
    if not isinstance(event, EventDefinition):
        raise _value_invalid(
            f"需要 EventDefinition，得到 {type(event).__name__}"
        )
    if not isinstance(values, (list, tuple)):
        raise _value_invalid(
            f"values 必须是 list 或 tuple，得到 {type(values).__name__}"
        )
    if len(values) != len(event.inputs):
        raise _value_invalid(
            f"values 数量应为 {len(event.inputs)}，得到 {len(values)}"
        )

    try:
        topics: list[bytes] = []
        if not event.anonymous:
            topics.append(bytes.fromhex(event_topic0(event)[2:]))

        indexed_topics: list[bytes] = []
        non_indexed_values: list = []
        for param, value in zip(event.inputs, values):
            if param.indexed:
                indexed_topics.append(_encode_indexed_topic(param.abi_type, value))
            else:
                non_indexed_values.append(value)
        topics.extend(indexed_topics)

        if non_indexed_values:
            data_type = TupleType(
                tuple(param.abi_type for param in event.inputs if not param.indexed)
            )
            data = _encode(data_type, tuple(non_indexed_values))
        else:
            data = b""
    except (ABIValueError, ABITypeError) as exc:
        raise _value_invalid(f"事件值编码失败：{exc}") from None

    return EncodedEventLog(event, tuple(topics), data)


# ---- 候选值核验 ------------------------------------------------------------


def match_event_log_values(event: EventDefinition, topics, data, values):
    """核验一组候选值是否与事件日志一致。

    先委托 :func:`decode_event_log` 完成全部日志校验——topics 容器与数量、
    非匿名事件的 topic0、可还原 indexed 基础值的严格解码，以及非 indexed
    参数 data 的严格 ABI 解码；这些失败沿用 :func:`decode_event_log` 的
    :class:`abi_kit.AbiEventError` 与错误码（EVENT_TOPIC_COUNT /
    EVENT_TOPIC0_MISMATCH / EVENT_TOPIC_VALUE / EVENT_DATA_INVALID），
    event 不是 :class:`EventDefinition` 时同样得到 ``EVENT_ABI_INVALID``。

    校验通过后，``values`` 按参数声明顺序排列，接受 list 或 tuple，数量
    必须与事件参数数相等，否则抛 code 为 ``EVENT_VALUE_INVALID`` 的
    :class:`abi_kit.AbiEventError`。逐位比较候选：

    - 非 indexed 候选等于 data 解码值；
    - indexed 的 address/bool/intM/uintM/bytesM 候选等于 topic 解码值；
    - indexed 的 string、动态 bytes、数组与 tuple 不可逆，候选按
      :func:`encode_event_log` 的事件索引特殊编码重算 32 字节 Keccak-256
      主题，与日志中的 topic 逐字节比较；候选值无法生成其声明类型的索引
      值时抛 ``EVENT_VALUE_INVALID``。

    全部一致时按声明顺序返回候选值 tuple；任一值或重算哈希不同则返回
    None（不抛错）。动态哈希主题不可逆，核验只比较哈希，不还原原值。
    """
    # 先完成主题数量、topic0、topic 基础值与 data 的全部严格校验；event
    # 类型错误在此同样得到 EVENT_ABI_INVALID。
    decoded = decode_event_log(event, topics, data)

    if not isinstance(values, (list, tuple)):
        raise _value_invalid(
            f"values 必须是 list 或 tuple，得到 {type(values).__name__}"
        )
    if len(values) != len(event.inputs):
        raise _value_invalid(
            f"values 数量应为 {len(event.inputs)}，得到 {len(values)}"
        )

    try:
        for param, candidate, actual in zip(event.inputs, values, decoded):
            if param.indexed and _is_hashed_indexed_type(param.abi_type):
                # 动态 indexed：按事件索引特殊编码重算 32 字节主题，与日志
                # 中 decode_event_log 原样保留的 topic bytes 逐字节比较。
                if _encode_indexed_topic(param.abi_type, candidate) != actual:
                    return None
            elif candidate != actual:
                # 非 indexed 值或可还原 indexed 基础值直接与解码值比较。
                return None
    except (ABIValueError, ABITypeError) as exc:
        raise _value_invalid(
            f"动态 indexed 候选值无法生成声明类型索引值：{exc}"
        ) from None

    return tuple(values)

"""Solidity error ABI 解析、selector 与 revert data 编解码。

- :func:`parse_error_abi`：解析 ABI JSON 字符串或等价条目数组，只消费
  ``type == "error"`` 的条目，按声明顺序返回不可变
  :class:`ErrorDefinition`；function / event / constructor / receive /
  fallback 条目跳过不解析。
- :func:`canonical_error_signature`：返回 ``Name(type1,type2,...)`` 形式
  的规范错误签名（参数名不参与）。
- :func:`error_selector`：返回 ``keccak256(规范签名)[:4]`` 的四字节
  selector（bytes）。
- :func:`encode_error_data`：按错误名（无重载时）或规范签名选择 error，
  按 inputs 声明顺序把 list/tuple 实参编码为 ``selector + ABI(参数
  tuple)`` 的完整 revert data，返回 :class:`EncodedErrorData`。
- :func:`decode_error_data`：按 revert data 前四字节 selector 定位
  error，再严格解码参数 tuple，返回 :class:`DecodedErrorData`，携带
  名称、规范类型与值 tuple；无参数 error 的 revert data 即四字节
  selector，解码为空 tuple。

错误约定：

- 元数据非法（ABI 根不是数组、error 条目缺 name/type/inputs、标识符
  非法、参数类型字符串无法解析、规范签名重复等）抛
  :class:`abi_kit.AbiMetadataError`；
- 错误名或规范签名无匹配抛 :class:`abi_kit.AbiErrorNotFoundError`；
- 只给错误名但同名重载不止一个、无法唯一选择抛
  :class:`abi_kit.AbiErrorOverloadError`；
- revert data 少于四字节抛 :class:`abi_kit.AbiErrorDataLengthError`；
- selector 匹配不到任何 error 抛 :class:`abi_kit.AbiErrorSelectorError`；
- 实参不能按声明类型编码、或参数区不能按声明类型严格解码抛
  :class:`abi_kit.ABIValueError`；
- 参数消费完后仍有尾随字节抛 :class:`abi_kit.AbiErrorTrailingDataError`；
- revert data 不是 bytes 或可选 ``0x`` 前缀的偶数位十六进制字符串抛
  :class:`abi_kit.ABIValueError`。
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field

from ._codec import _decode, _encode
from ._event import _build_type, _is_identifier
from ._exceptions import (
    AbiErrorDataLengthError,
    AbiErrorNotFoundError,
    AbiErrorOverloadError,
    AbiErrorSelectorError,
    AbiErrorTrailingDataError,
    AbiEventError,
    AbiMetadataError,
    ABITypeError,
    ABIValueError,
)
from ._format import format_abi_type
from ._keccak import keccak_256
from ._types import ABIType, TupleType

_SELECTOR_LEN = 4
_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")

#: error 路径跳过但允许保留在 ABI 中的非 error 条目类型；这些条目的合法性
#: 由各自入口（如函数、事件路径）负责，本模块不解析。
_NON_ERROR_ENTRY_TYPES = frozenset(
    ("function", "event", "constructor", "receive", "fallback")
)


# ---- 不可变定义与结果对象 -------------------------------------------------


@dataclass(frozen=True)
class ErrorArgument:
    """error 的单个参数（声明顺序保留）。

    - ``name``：ABI JSON 中的参数名，缺省为空串；
    - ``abi_type``：由 ``type`` + ``components`` 展开得到的类型对象；
    - ``value``：解码结果中按值层口径还原的 Python 值；定义中为 None。
    """

    name: str
    abi_type: ABIType
    value: object = None

    @property
    def type(self) -> str:
        """规范 ABI 类型字符串（不含空白与参数名）。"""
        return format_abi_type(self.abi_type)


@dataclass(frozen=True)
class ErrorDefinition:
    """不可变 error 定义。

    - ``name``：非空 ASCII 错误标识符；
    - ``inputs``：按声明顺序保存的 :class:`ErrorArgument`。
    """

    name: str
    inputs: tuple[ErrorArgument, ...] = field(default=())


@dataclass(frozen=True)
class EncodedErrorData:
    """error revert data 编码结果。

    - ``error``：命中的 :class:`ErrorDefinition`；
    - ``selector``：四字节 selector（bytes）；
    - ``data``：``selector + 参数 ABI 编码`` 的完整 revert data。
    """

    error: ErrorDefinition
    selector: bytes
    data: bytes

    @property
    def error_name(self) -> str:
        """命中 error 的名称。"""
        return self.error.name

    @property
    def signature(self) -> str:
        """命中 error 的规范签名，如 ``InsufficientBalance(address,uint256)``。"""
        return canonical_error_signature(self.error)

    @property
    def selector_hex(self) -> str:
        """``"0x"`` + 8 个小写十六进制字符形式的 selector。"""
        return "0x" + self.selector.hex()

    @property
    def data_hex(self) -> str:
        """``"0x"`` 前缀的完整 revert data 十六进制字符串。"""
        return "0x" + self.data.hex()


@dataclass(frozen=True)
class DecodedErrorData:
    """error revert data 解码结果。

    - ``error``：selector 命中的 :class:`ErrorDefinition`；
    - ``selector``：revert data 前四字节（bytes）；
    - ``args``：按声明顺序排列的 :class:`ErrorArgument`，``value`` 为
      还原值。
    """

    error: ErrorDefinition
    selector: bytes
    args: tuple[ErrorArgument, ...] = field(default=())

    @property
    def error_name(self) -> str:
        """命中 error 的名称。"""
        return self.error.name

    @property
    def signature(self) -> str:
        """命中 error 的规范签名，如 ``InsufficientBalance(address,uint256)``。"""
        return canonical_error_signature(self.error)

    @property
    def selector_hex(self) -> str:
        """``"0x"`` + 8 个小写十六进制字符形式的 selector。"""
        return "0x" + self.selector.hex()

    @property
    def types(self) -> tuple[str, ...]:
        """按声明顺序排列的规范 ABI 类型字符串 tuple。"""
        return tuple(arg.type for arg in self.args)

    @property
    def values(self) -> tuple:
        """按声明顺序去掉类型标注后的纯值 tuple。"""
        return tuple(arg.value for arg in self.args)


# ---- ABI 解析 -------------------------------------------------------------


def _metadata(message: str) -> AbiMetadataError:
    return AbiMetadataError(message)


def _parse_error_entry(entry: dict) -> ErrorDefinition:
    """从单个 ABI error 条目构造不可变错误定义。"""
    name = entry.get("name")
    if not _is_identifier(name):
        raise _metadata(f"error name 必须是非空 ASCII 标识符，得到 {name!r}")
    if "inputs" not in entry:
        raise _metadata(f"error {name!r} 缺少 inputs")
    inputs_node = entry["inputs"]
    if not isinstance(inputs_node, (list, tuple)):
        raise _metadata(f"error {name!r} 的 inputs 必须是数组")

    parameters: list[ErrorArgument] = []
    for node in inputs_node:
        if not isinstance(node, dict):
            raise _metadata(
                f"error {name!r} 的参数必须是 JSON 对象，"
                f"得到 {type(node).__name__}"
            )
        param_name = node.get("name", "")
        if not isinstance(param_name, str):
            raise _metadata(
                f"error {name!r} 的参数 name 必须是字符串，得到 {param_name!r}"
            )
        try:
            # 与事件、函数路径共用同一套 type + components 递归展开；其
            # 失败统一是事件层错误码，这里转译为 error 元数据错误。
            abi_type = _build_type(node)
        except (AbiEventError, ABITypeError) as exc:
            raise _metadata(f"error {name!r} 的参数类型非法：{exc}") from None
        parameters.append(ErrorArgument(param_name, abi_type))
    return ErrorDefinition(name, tuple(parameters))


def parse_error_abi(abi) -> tuple[ErrorDefinition, ...]:
    """解析 ABI，返回其中全部 error 条目的不可变定义。

    ``abi`` 接受 ABI JSON 字符串（:func:`json.loads` 口径）或等价的
    Python 条目数组（list/tuple）。只消费 ``type == "error"`` 的条目，
    按声明顺序返回；function、event、constructor、receive、fallback 等
    其他条目原样保留在 ABI 中但不解析、不影响 error 路径。error 条目的
    ``inputs`` 必填；签名只由 name 与 inputs 的规范类型构成，参数名不
    参与。任何 error 元数据非法（含规范签名重复）抛
    :class:`abi_kit.AbiMetadataError`。
    """
    if isinstance(abi, str):
        try:
            root = json.loads(abi)
        except (json.JSONDecodeError, ValueError) as exc:
            raise _metadata(f"ABI JSON 解析失败：{exc}") from None
    elif isinstance(abi, (list, tuple)):
        root = abi
    else:
        raise _metadata(
            f"ABI 必须是 JSON 字符串或条目数组，得到 {type(abi).__name__}"
        )

    if not isinstance(root, (list, tuple)):
        raise _metadata("ABI 必须是条目数组，JSON 根不能是对象或标量")

    errors: list[ErrorDefinition] = []
    for entry in root:
        if not isinstance(entry, dict):
            raise _metadata(
                f"ABI 条目必须是 JSON 对象，得到 {type(entry).__name__}"
            )
        entry_type = entry.get("type")
        # function/event/constructor/receive/fallback 条目保留在 ABI 中供
        # 各自入口使用，error 路径跳过且不校验；缺 type 或未知条目类型属
        # 元数据非法，统一抛 AbiMetadataError。
        if entry_type == "error":
            errors.append(_parse_error_entry(entry))
        elif entry_type in _NON_ERROR_ENTRY_TYPES:
            continue
        else:
            raise _metadata(
                f"ABI 条目缺少 type 或带有未知类型 {entry_type!r}，"
                "合法值为 function/event/constructor/error/receive/fallback"
            )

    seen: set[str] = set()
    for error in errors:
        signature = canonical_error_signature(error)
        if signature in seen:
            raise _metadata(f"error 规范签名重复：{signature!r}")
        seen.add(signature)
    return tuple(errors)


# ---- 规范签名与 selector --------------------------------------------------


def canonical_error_signature(error: ErrorDefinition) -> str:
    """返回规范错误签名 ``Name(type1,type2,...)``。

    参数名不参与签名；tuple 输出为 ``(t1,t2)``，数组保留 ``[]``/``[n]``
    后缀。
    """
    if not isinstance(error, ErrorDefinition):
        raise _metadata(
            f"需要 ErrorDefinition，得到 {type(error).__name__}"
        )
    canonical = ",".join(format_abi_type(p.abi_type) for p in error.inputs)
    return f"{error.name}({canonical})"


def error_selector(error: ErrorDefinition) -> bytes:
    """返回 error 四字节 selector：``keccak256(规范签名)[:4]``。"""
    signature = canonical_error_signature(error)
    try:
        digest = keccak_256(signature.encode("utf-8"))
    except (TypeError, ValueError) as exc:
        raise _metadata(f"规范签名无法生成 selector：{exc}") from None
    return digest[:_SELECTOR_LEN]


# ---- 选择 error -----------------------------------------------------------


def _resolve_error(errors: tuple[ErrorDefinition, ...], key) -> ErrorDefinition:
    """按错误名或规范签名在已解析 error 中唯一定位。"""
    if not isinstance(key, str) or not key:
        raise _metadata(f"错误名或规范签名必须是非空字符串，得到 {key!r}")

    if "(" in key or ")" in key:
        for error in errors:
            if canonical_error_signature(error) == key:
                return error
        raise AbiErrorNotFoundError(
            f"ABI 中找不到规范签名为 {key!r} 的 error"
        )

    if not _is_identifier(key):
        raise _metadata(f"非法错误名：{key!r}")

    candidates = [error for error in errors if error.name == key]
    if not candidates:
        raise AbiErrorNotFoundError(f"ABI 中找不到 error {key!r}")
    if len(candidates) > 1:
        signatures = ", ".join(
            canonical_error_signature(error) for error in candidates
        )
        raise AbiErrorOverloadError(
            f"error {key!r} 存在 {len(candidates)} 个重载，无法唯一选择，"
            f"请改用规范签名之一：{signatures}"
        )
    return candidates[0]


# ---- revert data 编解码 ---------------------------------------------------


def _coerce_error_data(data) -> bytes:
    """把 bytes 或可选 0x 前缀的偶数位十六进制字符串规范化为 bytes。"""
    if isinstance(data, bytes):
        return data
    if isinstance(data, str):
        text = data[2:] if data[:2] in ("0x", "0X") else data
        if len(text) % 2 or any(c not in _HEX_DIGITS for c in text):
            raise ABIValueError(
                "revert data 必须是可选 0x 前缀的偶数位十六进制字符串"
            )
        return bytes.fromhex(text)
    raise ABIValueError(
        f"revert data 必须是 bytes 或十六进制 str，得到 {type(data).__name__}"
    )


def _input_types(error: ErrorDefinition) -> TupleType:
    return TupleType(tuple(parameter.abi_type for parameter in error.inputs))


def encode_error_data(abi, error_name, args=None) -> EncodedErrorData:
    """编码一次 error revert data。

    ``abi`` 接受 ABI JSON 字符串或等价条目数组；``error_name`` 接受
    错误名（ABI 中无同名重载时）或规范错误签名
    （``InsufficientBalance(address,uint256)``）；``args`` 为按 inputs
    声明顺序排列的实参列表（list/tuple），无参 error 可省略。

    返回 :class:`EncodedErrorData`，其中 ``selector`` 为四字节 bytes，
    ``data`` 为 ``selector + 参数 tuple 的 ABI 编码`` 的完整 revert
    data。实参不能按声明类型编码（含数量不符）抛
    :class:`abi_kit.ABIValueError`。
    """
    errors = parse_error_abi(abi)
    error = _resolve_error(errors, error_name)

    if args is None:
        values = ()
    elif isinstance(args, (list, tuple)):
        values = tuple(args)
    else:
        raise ABIValueError(
            f"实参列表必须是 list 或 tuple，得到 {type(args).__name__}"
        )

    payload = _encode(_input_types(error), values)
    selector = error_selector(error)
    return EncodedErrorData(error, selector, selector + payload)


def decode_error_data(abi, data) -> DecodedErrorData:
    """解码完整 error revert data。

    ``data`` 接受 bytes 或可选 ``0x`` 前缀的偶数位十六进制字符串，前四
    字节必须是 ABI 中某个 error 的 selector；其后按该 error inputs 组成
    的 tuple 严格 ABI 解码。返回 :class:`DecodedErrorData`，携带 error
    定义、selector、规范签名（属性）与按声明顺序排列的带类型标注参数；
    ``values`` 属性给出等价的纯值 tuple。无参数 error 的 revert data 即
    四字节 selector，解码为空 tuple。

    data 类型或十六进制非法抛 :class:`abi_kit.ABIValueError`；少于四字节
    抛 :class:`abi_kit.AbiErrorDataLengthError`；selector 无匹配抛
    :class:`abi_kit.AbiErrorSelectorError`；参数区不能严格解码抛
    :class:`abi_kit.ABIValueError`；解码后仍有尾随字节抛
    :class:`abi_kit.AbiErrorTrailingDataError`。
    """
    errors = parse_error_abi(abi)
    raw = _coerce_error_data(data)

    if len(raw) < _SELECTOR_LEN:
        raise AbiErrorDataLengthError(
            f"revert data 长度必须至少为 {_SELECTOR_LEN} 字节以容纳 "
            f"selector，得到 {len(raw)} 字节"
        )
    selector = raw[:_SELECTOR_LEN]

    matches = [error for error in errors if error_selector(error) == selector]
    if not matches:
        raise AbiErrorSelectorError(
            f"selector 0x{selector.hex()} 在 ABI 中匹配不到任何 error"
        )
    error = matches[0]

    payload = raw[_SELECTOR_LEN:]
    bound = len(payload)
    values, end = _decode(_input_types(error), payload, 0, bound)
    if end != bound:
        raise AbiErrorTrailingDataError(
            f"参数解码完成后仍有 {bound - end} 字节尾随数据未被消费"
        )

    arguments = tuple(
        ErrorArgument(parameter.name, parameter.abi_type, value)
        for parameter, value in zip(error.inputs, values)
    )
    return DecodedErrorData(error, selector, arguments)

"""合约调用分派：统一处理 function、receive 与 fallback。

- :func:`parse_contract_call_registry`：解析 ABI JSON 字符串或等价条目
  数组，只登记 ``type == "function" / "receive" / "fallback"`` 的条目，
  按 ABI 声明顺序构建不可变 :class:`ContractCallRegistry`；event /
  constructor / error 等其他条目跳过不解析。function 保留名称、inputs、
  outputs 与 selector 语义（与 :class:`abi_kit.FunctionDefinition` 完全
  一致）；receive / fallback 至多各登记一个且不接受 inputs；function 的
  规范签名不得重复。
- :func:`encode_contract_call`：``target`` 接受无同名重载的函数名、规范
  函数签名，或字面量 ``"receive"`` / ``"fallback"``。函数按 inputs 顺序
  编码实参，返回 ``selector + 参数区`` 的完整 calldata；receive 仅接受
  空实参与空 data，calldata 为 ``b""``；fallback 仅接受空实参，并把
  data 原样放入 calldata。
- :func:`decode_contract_call`：按完整 calldata 分派并严格解码。空
  calldata 优先分派 receive，无 receive 时分派 fallback；前四字节命中
  函数 selector 时按函数 inputs 严格解码；未知 selector（或短于四字节
  的非空 calldata）有 fallback 时分派 fallback，否则报告目标不存在。返回
  :class:`DecodedContractCall`（``kind`` / ``function`` / ``args`` /
  ``data`` / ``calldata``）：``function`` 为
  :class:`abi_kit.FunctionDefinition` 或 ``None``，``args`` 为
  :class:`abi_kit.FunctionArgument` tuple；函数的 ``data`` 为参数区，
  fallback 的 ``data`` 为完整 calldata，receive 的 ``data`` 为空字节。

错误约定：

- 注册表构建、目标选择与数据口径失败统一抛
  :class:`abi_kit.AbiContractCallError`，以 ``code`` 唯一区分
  （CONTRACT_CALL_ABI_INVALID / CONTRACT_CALL_TARGET_NOT_FOUND /
  CONTRACT_CALL_AMBIGUOUS / CONTRACT_CALL_DATA_INVALID /
  CONTRACT_CALL_RECEIVE_NONEMPTY / CONTRACT_CALL_FALLBACK_ARGS）；
- 函数实参不能按声明类型编码、或参数区不能按声明类型严格解码仍抛
  :class:`abi_kit.ABIValueError`；参数解码完成后仍有尾随字节继续抛
  :class:`abi_kit.AbiTrailingDataError`；
- 调用层任一步失败即整体抛出，不返回部分结果。
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field

from ._codec import _decode, _encode
from ._exceptions import (
    AbiContractCallError,
    AbiMetadataError,
    AbiTrailingDataError,
    ABIValueError,
)
from ._format import format_abi_type
from ._function import (
    FunctionArgument,
    FunctionDefinition,
    _parse_function_entry,
    canonical_function_signature,
    function_selector,
)
from ._types import TupleType

_SELECTOR_LEN = 4

#: 分派结果的三类目标名称，同时作为 ABI 条目类型与 target 字面量。
KIND_FUNCTION = "function"
KIND_RECEIVE = "receive"
KIND_FALLBACK = "fallback"

_RECEIVE_TARGET = frozenset((KIND_RECEIVE,))
_FALLBACK_TARGET = frozenset((KIND_FALLBACK,))

_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")

#: 注册表登记的三类 ABI 条目。
_CALL_ENTRY_TYPES = frozenset(
    (KIND_FUNCTION, KIND_RECEIVE, KIND_FALLBACK)
)
#: 跳过的其余 ABI 条目类型；其合法性由各自入口负责。
_SKIPPED_ENTRY_TYPES = frozenset(("event", "constructor", "error"))


# ---- 不可变注册表与结果对象 -----------------------------------------------


@dataclass(frozen=True)
class ContractCallRegistry:
    """不可变合约调用注册表。

    - ``functions``：按 ABI 顺序保存的 :class:`FunctionDefinition` tuple；
    - ``receive``：是否登记了至多一个 receive 条目；
    - ``fallback``：是否登记了至多一个 fallback 条目。

    名称、规范签名与 selector 的查找索引在构造时预计算；条目合法性与
    唯一性约束由 :func:`parse_contract_call_registry` 校验。
    """

    functions: tuple[FunctionDefinition, ...] = field(default=())
    receive: bool = False
    fallback: bool = False
    _by_signature: dict = field(init=False, repr=False, compare=False)
    _by_name: dict = field(init=False, repr=False, compare=False)
    _by_selector: dict = field(init=False, repr=False, compare=False)

    def __post_init__(self):
        by_signature: dict = {}
        by_name: dict = {}
        by_selector: dict = {}
        for function in self.functions:
            by_signature[canonical_function_signature(function)] = function
            by_name.setdefault(function.name, []).append(function)
            by_selector.setdefault(function_selector(function), function)
        object.__setattr__(self, "_by_signature", by_signature)
        object.__setattr__(self, "_by_name", by_name)
        object.__setattr__(self, "_by_selector", by_selector)

    def __len__(self) -> int:
        return len(self.functions) + int(self.receive) + int(self.fallback)


@dataclass(frozen=True)
class DecodedContractCall:
    """合约调用解码结果。

    - ``kind``：``"function"`` / ``"receive"`` / ``"fallback"``；
    - ``function``：函数分派时为命中的 :class:`FunctionDefinition`，
      receive / fallback 分派时为 ``None``；
    - ``args``：按声明顺序排列的 :class:`FunctionArgument`，receive /
      fallback 为空 tuple；
    - ``data``：函数分派时为去掉 selector 的参数区，fallback 分派时为
      完整 calldata，receive 分派时为空字节；
    - ``calldata``：规范化后的完整 calldata bytes。
    """

    kind: str
    function: FunctionDefinition | None
    args: tuple[FunctionArgument, ...]
    data: bytes
    calldata: bytes

    @property
    def function_name(self) -> str | None:
        """命中函数的名称；receive / fallback 分派时为 ``None``。"""
        return None if self.function is None else self.function.name

    @property
    def signature(self) -> str | None:
        """命中函数的规范签名；receive / fallback 分派时为 ``None``。"""
        if self.function is None:
            return None
        return canonical_function_signature(self.function)

    @property
    def values(self) -> tuple:
        """按声明顺序去掉类型标注后的纯值 tuple。"""
        return tuple(arg.value for arg in self.args)

    @property
    def data_hex(self) -> str:
        """``"0x"`` 前缀的 data 小写十六进制字符串。"""
        return "0x" + self.data.hex()

    @property
    def calldata_hex(self) -> str:
        """``"0x"`` 前缀的完整 calldata 小写十六进制字符串。"""
        return "0x" + self.calldata.hex()


# ---- 异常构造与 ABI 规范化 ------------------------------------------------


def _error(code: str, message: str) -> AbiContractCallError:
    return AbiContractCallError(code, message)


def _load_abi_root(abi):
    """把 ABI JSON 字符串或等价条目数组规范化为根数组。"""
    if isinstance(abi, str):
        try:
            root = json.loads(abi)
        except (json.JSONDecodeError, ValueError) as exc:
            raise _error(
                "CONTRACT_CALL_ABI_INVALID", f"ABI JSON 解析失败：{exc}"
            ) from None
    elif isinstance(abi, (list, tuple)):
        root = abi
    else:
        raise _error(
            "CONTRACT_CALL_ABI_INVALID",
            f"ABI 必须是 JSON 字符串或条目数组，得到 {type(abi).__name__}",
        )
    if not isinstance(root, (list, tuple)):
        raise _error(
            "CONTRACT_CALL_ABI_INVALID",
            "ABI 必须是条目数组，JSON 根不能是对象或标量",
        )
    return root


def _validate_no_inputs(entry: dict, entry_type: str) -> None:
    """receive / fallback 条目不接受 inputs。"""
    if "inputs" not in entry:
        return
    inputs = entry["inputs"]
    if not isinstance(inputs, (list, tuple)) or inputs:
        raise _error(
            "CONTRACT_CALL_ABI_INVALID",
            f"{entry_type} 条目不接受 inputs，得到 {inputs!r}",
        )


def parse_contract_call_registry(abi) -> ContractCallRegistry:
    """解析 ABI，构建 function / receive / fallback 调用注册表。

    ``abi`` 接受 ABI JSON 字符串（:func:`json.loads` 口径）或等价的
    Python 条目数组（list/tuple）。只登记 ``type == "function"``、
    ``"receive"``、``"fallback"`` 的条目；event / constructor / error、
    缺 type、未知类型或非对象条目一律跳过不解析。function 条目语义同
    :func:`abi_kit.parse_function_abi`（name、inputs、outputs、selector），
    规范签名不得重复；receive / fallback 至多各登记一个且不接受 inputs。

    ABI 根非法、三类条目非法或重复登记时抛
    :class:`abi_kit.AbiContractCallError`（code 为
    ``CONTRACT_CALL_ABI_INVALID``）。
    """
    if isinstance(abi, ContractCallRegistry):
        return abi
    root = _load_abi_root(abi)

    functions: list[FunctionDefinition] = []
    signatures: set[str] = set()
    receive = False
    fallback = False
    for entry in root:
        if not isinstance(entry, dict):
            # 非对象条目不可能是三类调用条目，跳过不解析。
            continue
        entry_type = entry.get("type")
        if entry_type == KIND_FUNCTION:
            try:
                function = _parse_function_entry(entry)
            except AbiMetadataError as exc:
                # _parse_function_entry 的元数据失败统一转译为调用分派层
                # 的条目非法错误。
                raise _error(
                    "CONTRACT_CALL_ABI_INVALID",
                    f"function 条目非法：{exc}",
                ) from None
            signature = canonical_function_signature(function)
            if signature in signatures:
                raise _error(
                    "CONTRACT_CALL_ABI_INVALID",
                    f"函数规范签名重复：{signature}",
                )
            signatures.add(signature)
            functions.append(function)
        elif entry_type in _RECEIVE_TARGET:
            _validate_no_inputs(entry, KIND_RECEIVE)
            if receive:
                raise _error(
                    "CONTRACT_CALL_ABI_INVALID",
                    "ABI 中至多允许一个 receive 条目，检测到多个",
                )
            receive = True
        elif entry_type in _FALLBACK_TARGET:
            _validate_no_inputs(entry, KIND_FALLBACK)
            if fallback:
                raise _error(
                    "CONTRACT_CALL_ABI_INVALID",
                    "ABI 中至多允许一个 fallback 条目，检测到多个",
                )
            fallback = True
        elif entry_type in _SKIPPED_ENTRY_TYPES:
            continue
        else:
            # 缺 type 或未知类型条目跳过不登记。
            continue

    return ContractCallRegistry(tuple(functions), receive, fallback)


def _as_registry(abi) -> ContractCallRegistry:
    """接受注册表本身或原始 ABI，返回注册表。"""
    if isinstance(abi, ContractCallRegistry):
        return abi
    return parse_contract_call_registry(abi)


# ---- 实参与 data 规范化 ----------------------------------------------------


def _normalize_args(args) -> tuple:
    """把实参 list/tuple 规范化为 tuple；容器类型非法是值层错误。"""
    if args is None:
        return ()
    if isinstance(args, (list, tuple)):
        return tuple(args)
    raise ABIValueError(
        f"实参列表必须是 list 或 tuple，得到 {type(args).__name__}"
    )


def _coerce_call_data(data, noun: str) -> bytes:
    """把 bytes 或可选 0x 前缀的偶数位十六进制字符串规范化为 bytes。

    任何失败统一抛 ``CONTRACT_CALL_DATA_INVALID``。
    """
    if isinstance(data, bytes):
        return data
    if isinstance(data, str):
        text = data[2:] if data[:2] in ("0x", "0X") else data
        if len(text) % 2 or any(c not in _HEX_DIGITS for c in text):
            raise _error(
                "CONTRACT_CALL_DATA_INVALID",
                f"{noun}必须是可选 0x 前缀的偶数位十六进制字符串",
            )
        return bytes.fromhex(text)
    raise _error(
        "CONTRACT_CALL_DATA_INVALID",
        f"{noun}必须是 bytes 或十六进制 str，得到 {type(data).__name__}",
    )


# ---- 目标选择 --------------------------------------------------------------


def _resolve_function(
    registry: ContractCallRegistry, key: str
) -> FunctionDefinition:
    """按函数名或规范签名在注册表中唯一定位函数。"""
    if "(" in key or ")" in key:
        function = registry._by_signature.get(key)
        if function is None:
            raise _error(
                "CONTRACT_CALL_TARGET_NOT_FOUND",
                f"注册表中找不到规范签名为 {key!r} 的函数",
            )
        return function

    candidates = registry._by_name.get(key, [])
    if not candidates:
        raise _error(
            "CONTRACT_CALL_TARGET_NOT_FOUND",
            f"注册表中找不到函数 {key!r}",
        )
    if len(candidates) > 1:
        signatures = ", ".join(
            canonical_function_signature(function) for function in candidates
        )
        raise _error(
            "CONTRACT_CALL_AMBIGUOUS",
            f"函数 {key!r} 存在 {len(candidates)} 个重载，无法唯一选择，"
            f"请改用规范签名之一：{signatures}",
        )
    return candidates[0]


def _resolve_target(registry: ContractCallRegistry, target) -> str:
    """解析 target 字面量并校验 receive/fallback 存在性。

    返回 ``"receive"`` / ``"fallback"``；函数目标由调用方继续解析，
    非特殊字面量时返回 ``"function"``。
    """
    if not isinstance(target, str) or not target:
        raise _error(
            "CONTRACT_CALL_TARGET_NOT_FOUND",
            f"target 必须是非空字符串，得到 {target!r}",
        )
    if target == KIND_RECEIVE:
        if not registry.receive:
            raise _error(
                "CONTRACT_CALL_TARGET_NOT_FOUND",
                "注册表中没有 receive 条目",
            )
        return KIND_RECEIVE
    if target == KIND_FALLBACK:
        if not registry.fallback:
            raise _error(
                "CONTRACT_CALL_TARGET_NOT_FOUND",
                "注册表中没有 fallback 条目",
            )
        return KIND_FALLBACK
    return KIND_FUNCTION


# ---- 编码 ------------------------------------------------------------------


def encode_contract_call(abi, target, args=None, data=None) -> bytes:
    """按 target 编码一次合约调用，返回完整 calldata bytes。

    ``abi`` 接受 :class:`ContractCallRegistry` 或 ABI JSON 字符串/等价
    条目数组（每次调用按同一套规则解析）；``target`` 接受无同名重载的
    函数名、规范函数签名（``transfer(address,uint256)``），或字面量
    ``"receive"`` / ``"fallback"``。

    - 函数：``args`` 为按 inputs 声明顺序排列的实参 list/tuple，返回
      ``selector + 参数 tuple 的 ABI 编码``；实参不能按声明类型编码
      （含数量不符）抛 :class:`abi_kit.ABIValueError`。
    - receive：仅接受空实参与空 data（``data`` 缺省即空），返回
      ``b""``；非空实参或非空 data 抛
      :class:`abi_kit.AbiContractCallError`
      （``CONTRACT_CALL_RECEIVE_NONEMPTY``）。
    - fallback：仅接受空实参，``data``（bytes 或可选 ``0x`` 前缀的偶数
      位十六进制字符串，缺省为空）原样作为 calldata 返回；给出非空实参
      抛 :class:`abi_kit.AbiContractCallError`
      （``CONTRACT_CALL_FALLBACK_ARGS``）。

    目标不存在、函数名歧义与 data 口径非法分别抛
    :class:`abi_kit.AbiContractCallError` 的对应唯一错误码。
    """
    registry = _as_registry(abi)
    kind = _resolve_target(registry, target)
    values = _normalize_args(args)

    if kind == KIND_RECEIVE:
        if values:
            raise _error(
                "CONTRACT_CALL_RECEIVE_NONEMPTY",
                "receive 不接受实参，编码 calldata 必须为空",
            )
        raw = _coerce_call_data(
            b"" if data is None else data, "receive data "
        )
        if raw:
            raise _error(
                "CONTRACT_CALL_RECEIVE_NONEMPTY",
                "receive 只接受空 data，calldata 必须为空字节",
            )
        return b""

    if kind == KIND_FALLBACK:
        if values:
            raise _error(
                "CONTRACT_CALL_FALLBACK_ARGS",
                "fallback 不接受实参，只接受原样 data",
            )
        return _coerce_call_data(
            b"" if data is None else data, "fallback data "
        )

    function = _resolve_function(registry, target)
    if data is not None:
        raise _error(
            "CONTRACT_CALL_DATA_INVALID",
            "function 目标不接受 data，实参必须通过 args 提供",
        )
    parameter_types = TupleType(
        tuple(parameter.abi_type for parameter in function.inputs)
    )
    payload = _encode(parameter_types, values)
    return function_selector(function) + payload


# ---- 解码与分派 ------------------------------------------------------------


def _decode_function_call(
    registry: ContractCallRegistry, raw: bytes
) -> DecodedContractCall:
    """按前四字节 selector 分派函数并严格解码参数区。"""
    selector = raw[:_SELECTOR_LEN]
    function = registry._by_selector.get(selector)
    if function is None:
        return None

    parameter_types = TupleType(
        tuple(parameter.abi_type for parameter in function.inputs)
    )
    payload = raw[_SELECTOR_LEN:]
    bound = len(payload)
    values, end = _decode(parameter_types, payload, 0, bound)
    if end != bound:
        raise AbiTrailingDataError(
            f"参数解码完成后仍有 {bound - end} 字节尾随数据未被消费"
        )
    arguments = tuple(
        FunctionArgument(
            parameter.name, format_abi_type(parameter.abi_type), value
        )
        for parameter, value in zip(function.inputs, values)
    )
    return DecodedContractCall(
        KIND_FUNCTION, function, arguments, payload, raw
    )


def decode_contract_call(abi, calldata) -> DecodedContractCall:
    """按完整 calldata 分派并严格解码一次合约调用。

    ``abi`` 接受 :class:`ContractCallRegistry` 或 ABI JSON 字符串/等价
    条目数组；``calldata`` 接受 bytes 或可选 ``0x`` 前缀的偶数位十六进制
    字符串。分派顺序：

    1. 空 calldata 优先分派 receive；注册表无 receive 时分派 fallback；
       两者都没有时报告目标不存在。
    2. 非空 calldata 前四字节命中函数 selector 时，按该函数 inputs 组成
       的 tuple 严格解码参数区；参数区非法抛
       :class:`abi_kit.ABIValueError`，解码后仍有尾随字节抛
       :class:`abi_kit.AbiTrailingDataError`。
    3. 未知 selector（含短于四字节的非空 calldata）在注册表存在
       fallback 时分派 fallback（``data`` 即完整 calldata），否则报告
       目标不存在。

    返回 :class:`DecodedContractCall`，含 ``kind`` / ``function`` /
    ``args`` / ``data`` / ``calldata``；receive 的 ``data`` 为空字节，
    fallback 的 ``data`` 为完整 calldata。任一步失败即整体抛出，不返回
    部分结果。
    """
    registry = _as_registry(abi)
    raw = _coerce_call_data(calldata, "calldata ")

    if not raw:
        # 空 calldata 优先分派 receive，否则退回 fallback；两者都没有
        # 才报告目标不存在。
        if registry.receive:
            return DecodedContractCall(KIND_RECEIVE, None, (), b"", raw)
        if registry.fallback:
            return DecodedContractCall(KIND_FALLBACK, None, (), raw, raw)
        raise _error(
            "CONTRACT_CALL_TARGET_NOT_FOUND",
            "空 calldata 优先分派 receive、其次 fallback，"
            "但注册表中两者都不存在",
        )

    result = _decode_function_call(registry, raw)
    if result is not None:
        return result

    if registry.fallback:
        return DecodedContractCall(KIND_FALLBACK, None, (), raw, raw)
    selector_preview = raw[:_SELECTOR_LEN]
    raise _error(
        "CONTRACT_CALL_TARGET_NOT_FOUND",
        "calldata 的前四字节 "
        f"0x{selector_preview.hex()} 未匹配任何函数，且注册表中没有 "
        "fallback 条目可供分派",
    )

